kernels.wgsl:
@group(0) @binding(0) var<storage, read> b0: array<f32>;
@group(0) @binding(1) var<storage, read> b1: array<f32>;
@group(0) @binding(2) var<storage, read_write> bout: array<f32>;

@compute @workgroup_size(64)
fn main(@builtin(local_invocation_index) lid: u32, @builtin(workgroup_id) wid: vec3<u32>, @builtin(num_workgroups) nwg: vec3<u32>) {
    let tid: i32 = i32(lid);
    let bid: i32 = i32(wid.x) + i32(wid.y) * i32(nwg.x);
    if (bid >= 3072i) { return; }
    var v_in0: f32 = 0.0;
    var v_in1: f32 = 0.0;
    var v_v0: f32 = 0.0;
    var n_e: i32 = 0i;
    n_e = ((64i * bid) + tid);
    if (n_e < 196608i) {
        v_in0 = b0[((((((16i * ((n_e / 16i) % 16i)) + (n_e % 16i)) + (256i * (n_e / 256i))) / 256i) % 768i) + (768i * (((16i * ((n_e / 16i) % 16i)) + (n_e % 16i)) % 256i)))];
        v_in1 = b1[((((((16i * ((n_e / 16i) % 16i)) + (n_e % 16i)) + (256i * (n_e / 256i))) / 256i) % 768i) + (768i * (((16i * ((n_e / 16i) % 16i)) + (n_e % 16i)) % 256i)))];
        v_v0 = (v_in0 + v_in1);
        bout[(((16i * ((n_e / 16i) % 16i)) + (n_e % 16i)) + (256i * (n_e / 256i)))] = v_v0;
    }
}
